window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cd97c44234666b3c"]={"versions": [{"id": "FIG-cd97c44234666b3c", "releases": ["R3.0.7", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Notizblock bzw. Metadaten-Platzhalter für die AUTOSAR-Methodik auf Komponentenebene (Per-Component-Workflow). Die Darstellung enthält kein vollständiges Prozessmodell, sondern ausschließlich administrative Metadatenfelder zu Dokumentations- und Spezifikationszwecken.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Enthalten ist ein einzelnes Notiz-Element mit folgenden textuellen Feldern:</p>\n<ul class=\"fig-list\">\n<li><code>Status</code>: <code>proposed (proposed, approved, rejected)</code></li>\n<li><code>Description</code>: <code>per Component The workflow and the necessary activities in terms of the AUTOSAR methodology to start the development of an application software component and to integrate it later into the system. These activities have to be performed for every application software component.</code></li>\n<li><code>Comment</code>: <code>-</code></li>\n</ul>\n<p class=\"fig-p\">Es sind keine Software-Komponenten, Entitäten, Schnittstellen oder Datenartefakte dargestellt.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Kein dynamischer Ablauf oder Kontrollfluss visualisiert; es liegt eine rein statische Metadaten-Notiz ohne Verhaltenssemantik vor.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild besitzt rein informativen Charakter als Spezifikationsplatzhalter für den geplanten Ablauf der Komponentenentwicklung („Status: proposed“). Für Software-Entwickler und Integratoren leiten sich aus dieser Fassung keine operativen Prozessvorgaben oder verbindlichen Schnittstellendefinitionen ab.</p>"}, {"id": "FIG-5007e6b831dcc927", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätendiagramm (SPEM-/UML-basiertes Prozessdiagramm) zur Spezifikation des entwicklungsbezogenen Ablaufs für Software-Komponenten („per Component part of the AUTOSAR methodology“). Das Diagramm stellt Aktivitäten, Artefakte (XML-Beschreibungen, C-Header, C-Quelldateien, Objektdateien) und Werkzeugeinsätze dar und wird links unten von einer Notizbox mit Status- und Metadaten begleitet.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Aktivitäten (gelbe Pfeilblöcke):</p>\n<ul class=\"fig-list\">\n<li><code>Generate Component API</code></li>\n<li><code>Implement Component</code></li>\n<li><code>Compile Component</code></li>\n<li><code>Measure Resources</code></li>\n</ul>\n<p class=\"fig-p\">Werkzeug (Tool-Symbol):</p>\n<ul class=\"fig-list\">\n<li><code>AUTOSAR Component API Generator</code></li>\n</ul>\n<p class=\"fig-p\">Artefakte und Modellelemente:</p>\n<ul class=\"fig-list\">\n<li>XML-Beschreibungen (.XML):</li>\n<li><code>Component Type Description : AtomicSoftwareComponentType</code></li>\n<li><code>Service Port : PortPrototype</code></li>\n<li><code>Standardized Service Interface : PortInterface</code></li>\n<li><code>Service Needs : ServiceNeeds</code></li>\n<li><code>Component Internal Behavior Description [API Generation] : InternalBehavior</code></li>\n<li><code>Component Internal Behavior Description [post Implementation] : InternalBehavior</code></li>\n<li><code>Component Implementation Description [for Source-Code] : Implementation</code></li>\n<li><code>Component Implementation Description [for Object-Code] : Implementation</code></li>\n<li><code>Component Implementation Description [resource needs] : Implementation</code></li>\n<li><code>ECU Resource Description : ECU</code></li>\n<li><code>Component Resource Consumption : ResourceConsumption</code></li>\n<li>Datei-Artefakte:</li>\n<li><code>Component API</code> (.h)</li>\n<li><code>Additional Headers</code> (.h)</li>\n<li><code>Component Implementation</code> (.c)</li>\n<li><code>Compiled Component</code> (.obj)</li>\n</ul>\n<p class=\"fig-p\">Notizbox:</p>\n<ul class=\"fig-list\">\n<li>Metadaten zu Status (<code>proposed</code>), Beschreibung des komponentenbezogenen Workflows und Kommentarfeld.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der sequenzielle Prozess gliedert sich in vier aufeinanderfolgende Phasen:</p>\n<ol class=\"fig-list\">\n<li><strong>API-Generierung</strong>: Ausgehend von <code>Component Internal Behavior Description [API Generation]</code> erzeugt der <code>AUTOSAR Component API Generator</code> die Header-Datei <code>Component API</code> (.h).</li>\n<li><strong>Komponenten-Implementierung</strong>: Die Aktivität <code>Implement Component</code> konsumiert die generierte <code>Component API</code> (.h) sowie die <code>Component Internal Behavior Description [API Generation]</code>. Im Zuge der Implementierung entstehen die C-Quelldatei <code>Component Implementation</code> (.c), die aktualisierte Verhaltensbeschreibung <code>Component Internal Behavior Description [post Implementation]</code> und die Implementierungsbeschreibung für Source-Code (<code>Component Implementation Description [for Source-Code]</code>). Zudem bestehen Querbeziehungen zu <code>Service Port</code>, <code>Standardized Service Interface</code> und <code>Service Needs</code>.</li>\n<li><strong>Kompilierung</strong>: <code>Compile Component</code> verarbeitet <code>Component Implementation</code> (.c), <code>Component API</code> (.h) und <code>Additional Headers</code> (.h) und erzeugt das Objektcode-Artefakt <code>Compiled Component</code> (.obj) sowie <code>Component Implementation Description [for Object-Code]</code>.</li>\n<li><strong>Ressourcenmessung</strong>: <code>Measure Resources</code> analysiert <code>Compiled Component</code> (.obj) unter Einbeziehung der <code>ECU Resource Description</code> und erzeugt <code>Component Resource Consumption</code> sowie die finale <code>Component Implementation Description [resource needs]</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlicher Entwicklungsablauf für jede AUTOSAR Application Software Component:</p>\n<ul class=\"fig-list\">\n<li>Für die Source-Code-Implementierung ist zwingend vorab die komponentenspezifische API über das Internal Behavior und den API-Generator zu erzeugen.</li>\n<li>Die Trennung von <code>InternalBehavior</code> vor und nach der Implementierung dokumentiert die Anreicherung von Service-Needs und Post-Implementation-Attributen.</li>\n<li>Die Kompilierung erfordert definierte <code>Additional Headers</code> neben der generierten <code>Component API</code>.</li>\n<li>Vor der System- oder ECU-Integration muss über die Objektcode-Analyse und die Ziel-ECU-Ressourcenbeschreibung die Ressourcenbedarfsbeschreibung (<code>Component Implementation Description [resource needs]</code>) finalisiert werden. Die Notizbox weist den Workflow weiterhin als <code>Status: proposed</code> aus.</li>\n</ul>"}], "trans": [{"from": "FIG-cd97c44234666b3c", "to": "FIG-5007e6b831dcc927", "fr": "R3.0.7", "tr": "R3.1.5", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Ersetzung des reinen Notiz-/Metadaten-Platzhalters durch das vollständige AUTOSAR-Methodik-Aktivitätendiagramm für Softwarekomponenten</li>\n<li>Ergänzung der Aktivitäten <code>Generate Component API</code>, <code>Implement Component</code>, <code>Compile Component</code> und <code>Measure Resources</code></li>\n<li>Ergänzung des Werkzeugs <code>AUTOSAR Component API Generator</code></li>\n<li>Ergänzung der XML-Artefakte <code>Component Type Description</code> (:AtomicSoftwareComponentType), <code>Component Internal Behavior Description [API Generation]</code> (:InternalBehavior), <code>Service Port</code> (:PortPrototype), <code>Standardized Service Interface</code> (:PortInterface), <code>Service Needs</code> (:ServiceNeeds), <code>Component Internal Behavior Description [post Implementation]</code> (:InternalBehavior), <code>Component Implementation Description [for Source-Code]</code> (:Implementation), <code>Component Implementation Description [for Object-Code]</code> (:Implementation), <code>ECU Resource Description</code> (:ECU), <code>Component Resource Consumption</code> (:ResourceConsumption) und <code>Component Implementation Description [resource needs]</code> (:Implementation)</li>\n<li>Ergänzung der Quell- und Binärartefakte <code>Component API</code> (.h), <code>Additional Headers</code> (.h), <code>Component Implementation</code> (.c) und <code>Compiled Component</code> (.obj) samt Kontroll- und Datenflüssen</li>\n</ul>"}, {"from": "FIG-5007e6b831dcc927", "to": "FIG-cd97c44234666b3c", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Entfernung des gesamten grafischen Aktivitäts-, Artefakt- und Werkzeug-Workflows für Softwarekomponenten</li>\n<li>Rückführung des Schaubilds auf den reinen Status- und Beschreibungs-Notizblock (Status: proposed)</li>\n</ul>"}]};
